//! Exact parity between [`KokoroG2p::chunks`] and reference Kokoro's
//! `KPipeline` chunking + `KModel.forward`'s phoneme-to-id mapping.
//!
//! The fixture (`tests/fixtures/kokoro_pipeline_oracle.json`) is checked in
//! and was generated by
//! `crates/boostr-audio/tests/tools/kokoro_pipeline_oracle/kokoro_pipeline_oracle.py`.
//! It holds, for `af_heart` (American English) and `bf_emma` (British
//! English), the exact (graphemes, phonemes, input_ids) chunk sequence
//! `KPipeline.__call__` would hand to `KModel.forward` for ~25 corpus
//! sentences, one paragraph split by a blank line, and one paragraph long
//! enough to force more than one chunk.
//!
//! This crate's G2P has no OOV fallback attached (a separate unit wires the
//! neural fallback in), matching how the fixture was generated
//! (`fallback=None`).

use boostr::model::audio::PhonemeVocab;
use boostr::model::audio::kokoro::KokoroPhonemeVocab;
use boostr_audio::kokoro::{Dialect, KokoroG2p};
use serde::Deserialize;
use std::collections::HashMap;

mod common;
use common::load_json;

#[derive(Debug, Deserialize)]
struct Fixture {
    vocab: HashMap<String, u32>,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    text: String,
    voices: Voices,
}

#[derive(Debug, Deserialize)]
struct Voices {
    af_heart: Vec<Chunk>,
    bf_emma: Vec<Chunk>,
}

#[derive(Debug, Deserialize)]
struct Chunk {
    graphemes: String,
    phonemes: String,
    input_ids: Vec<i64>,
}

/// Reference Kokoro's `KModel.forward`: one id per phoneme character the
/// vocab knows, bracketed by the reserved BOS/EOS id `0`.
fn input_ids(vocab: &KokoroPhonemeVocab, phonemes: &str) -> Vec<i64> {
    let mut ids = vec![0i64];
    let mut buf = [0u8; 4];
    for c in phonemes.chars() {
        if let Some(id) = vocab.lookup(c.encode_utf8(&mut buf)) {
            ids.push(i64::from(id));
        }
    }
    ids.push(0);
    ids
}

fn check_dialect(
    label: &str,
    got: &[boostr_audio::kokoro::TextChunk],
    want: &[Chunk],
    vocab: &KokoroPhonemeVocab,
    failures: &mut Vec<String>,
) {
    if got.len() != want.len() {
        failures.push(format!(
            "{label}: chunk count {} differs from the oracle's {}",
            got.len(),
            want.len()
        ));
        return;
    }
    for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
        if g.graphemes != w.graphemes {
            failures.push(format!(
                "{label}: chunk {i} graphemes {:?} != oracle {:?}",
                g.graphemes, w.graphemes
            ));
        }
        if g.phonemes != w.phonemes {
            failures.push(format!(
                "{label}: chunk {i} phonemes {:?} != oracle {:?}",
                g.phonemes, w.phonemes
            ));
        }
        let ids = input_ids(vocab, &g.phonemes);
        if ids != w.input_ids {
            failures.push(format!(
                "{label}: chunk {i} input_ids {ids:?} != oracle {:?}",
                w.input_ids
            ));
        }
    }
}

#[test]
fn matches_reference_kokoro_pipeline_chunking_and_ids() {
    let fixture_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/kokoro_pipeline_oracle.json");
    let fixture: Fixture = load_json(&fixture_path);
    let vocab = KokoroPhonemeVocab::new(fixture.vocab.clone());
    let g2p = KokoroG2p::new().unwrap_or_else(|e| panic!("KokoroG2p::new: {e}"));

    let mut failures = Vec::new();
    for case in &fixture.cases {
        let us = g2p
            .chunks(&case.text, Dialect::Us)
            .unwrap_or_else(|e| panic!("{}: US chunks: {e}", case.name));
        check_dialect(
            &format!("{} (US)", case.name),
            &us,
            &case.voices.af_heart,
            &vocab,
            &mut failures,
        );

        let gb = g2p
            .chunks(&case.text, Dialect::Gb)
            .unwrap_or_else(|e| panic!("{}: GB chunks: {e}", case.name));
        check_dialect(
            &format!("{} (GB)", case.name),
            &gb,
            &case.voices.bf_emma,
            &vocab,
            &mut failures,
        );
    }

    assert!(
        failures.is_empty(),
        "{} mismatch(es):\n{}",
        failures.len(),
        failures.join("\n")
    );
}
